draw:
var hc = 1240;
var Eph = hc / p.lam;
var K = Eph - p.phi;
var Vstop = K > 0 ? K : 0;
var flows = (K > 0) && (p.V < K);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var xc = W * 0.22, xa = W * 0.78;
var yTop = H * 0.18, yBot = H * 0.74;
var ymid = (yTop + yBot) / 2;
var gap = xa - xc;

// plates
ctx.strokeStyle = C.ink;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(xc, yTop); ctx.lineTo(xc, yBot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xa, yTop); ctx.lineTo(xa, yBot); ctx.stroke();
ctx.lineWidth = 1.5;

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("cathode", xc, yBot + 16);
ctx.fillText("anode", xa, yBot + 16);
ctx.fillText("retarding voltage " + p.V.toFixed(2) + " V", (xc + xa) / 2, H - 8);

// incoming light: three photon markers sliding in from the left
var i, s, px, py;
ctx.strokeStyle = C.accent;
for (i = 0; i < 3; i++) {
  s = ((t * 0.7 + i * 0.333) % 1);
  px = xc * s;
  py = yTop + (yBot - yTop) * (0.25 + 0.25 * i);
  ctx.beginPath();
  ctx.moveTo(px - 14, py);
  ctx.lineTo(px, py);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(px, py); ctx.lineTo(px - 5, py - 3.5); ctx.lineTo(px - 5, py + 3.5);
  ctx.closePath();
  ctx.fillStyle = C.accent;
  ctx.fill();
}
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("light, " + p.lam.toFixed(0) + " nm", 4, yTop - 6);

// electrons
var n = 4, reach, ex;
ctx.textAlign = "center";
for (i = 0; i < n; i++) {
  s = ((t * 0.55 + i / n) % 1);
  if (K <= 0) { continue; }
  if (flows) {
    ex = xc + gap * s;
  } else {
    reach = p.V > 0 ? Math.min(K / p.V, 1) : 1;
    ex = xc + gap * reach * (1 - (2 * s - 1) * (2 * s - 1));
  }
  py = ymid + (i - 1.5) * (yBot - yTop) * 0.16;
  ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(ex, py, 4, 0, Math.PI * 2); ctx.fill();
}

if (K <= 0) {
  ctx.fillStyle = C.figure;
  ctx.fillText("no emission: photon is below the work function", (xc + xa) / 2, ymid);
} else if (!flows) {
  ctx.strokeStyle = C.rule;
  ctx.setLineDash([3, 4]);
  var turn = xc + gap * Math.min(K / Math.max(p.V, 1e-9), 1);
  ctx.beginPath(); ctx.moveTo(turn, yTop); ctx.lineTo(turn, yBot); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.figure;
  ctx.fillText("turned back", turn, yTop - 6);
}

// ammeter
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(xc, yBot); ctx.lineTo(xc, H * 0.88);
ctx.lineTo(xa, H * 0.88); ctx.lineTo(xa, yBot);
ctx.stroke();
ctx.fillStyle = flows ? C.accent : C.faint;
ctx.beginPath(); ctx.arc((xc + xa) / 2, H * 0.88, 9, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("A", (xc + xa) / 2, H * 0.88 + 4);

out.note = "photon " + Eph.toFixed(2) + " eV, work function " + p.phi.toFixed(2)
  + " eV, Kmax " + (K > 0 ? K.toFixed(2) : "0.00") + " eV, stopping potential "
  + Vstop.toFixed(2) + " V, current " + (flows ? "flowing" : "zero");

var h = 4.136e-15;   // eV s
var pad = 46;
var fmax = 1.6e15;
var Vmax = 4.5;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var Vmin = -5.2;
var sv = (H - 34) / (Vmax - Vmin);
var yzero = 14 + Vmax * sv;

var X = function (f) { return pad + (W - pad * 1.2) * (f / fmax); };
var Y = function (v) { return yzero - v * sv; };

// axes
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.2;
ctx.beginPath(); ctx.moveTo(pad, 6); ctx.lineTo(pad, H - 8); ctx.stroke();
ctx.beginPath(); ctx.moveTo(pad - 6, Y(0)); ctx.lineTo(W - 6, Y(0)); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("frequency f  (10^15 Hz)", (W + pad) / 2, Y(0) + 32);
ctx.save();
ctx.translate(12, H / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText("stopping potential Vs (V)", 0, 0);
ctx.restore();

// ticks
var k, fv;
ctx.fillStyle = C.faint;
for (k = 0; k <= 3; k++) {
  fv = k * 0.5e15;
  ctx.beginPath(); ctx.moveTo(X(fv), Y(0)); ctx.lineTo(X(fv), Y(0) + 4);
  ctx.strokeStyle = C.rule; ctx.stroke();
  ctx.fillStyle = C.faint;
  ctx.textAlign = "center";
  ctx.fillText((k * 0.5).toFixed(1), X(fv), Y(0) + 16);
}
for (k = 1; k <= 4; k++) {
  ctx.beginPath(); ctx.moveTo(pad - 4, Y(k)); ctx.lineTo(pad, Y(k));
  ctx.strokeStyle = C.rule; ctx.stroke();
  ctx.fillStyle = C.faint;
  ctx.textAlign = "right";
  ctx.fillText(k.toFixed(0), pad - 6, Y(k) + 4);
}

var f0 = p.phi / h;

// line above threshold
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(X(f0), Y(0));
ctx.lineTo(X(fmax), Y(h * fmax - p.phi));
ctx.stroke();

// dashed continuation down to the intercept at -phi/e
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(X(0), Y(-p.phi));
ctx.lineTo(X(f0), Y(0));
ctx.stroke();
ctx.setLineDash([]);

// threshold marker
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(f0), Y(0), 4, 0, Math.PI * 2); ctx.fill();
ctx.textAlign = "left";
ctx.fillText("threshold f0", X(f0) + 6, Y(0) + 16);
ctx.fillText("intercept -phi/e", X(0) + 4, Y(-p.phi) + 4);

// slope triangle
var fa = f0 + 0.35e15, fb = fa + 0.35e15;
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(X(fa), Y(h * fa - p.phi));
ctx.lineTo(X(fb), Y(h * fa - p.phi));
ctx.lineTo(X(fb), Y(h * fb - p.phi));
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("slope = h/e", X(fb) + 6, Y(h * fa - p.phi) - 4);

// moving measurement point
var fnow = f0 + (fmax - f0) * (0.5 - 0.5 * Math.cos(t * 0.7));
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(fnow), Y(h * fnow - p.phi), 5, 0, Math.PI * 2); ctx.fill();

out.note = "work function " + p.phi.toFixed(2) + " eV, threshold " + (f0 / 1e14).toFixed(2)
  + " x 10^14 Hz (" + (1240 / p.phi).toFixed(0) + " nm); at f = "
  + (fnow / 1e14).toFixed(2) + " x 10^14 Hz the stopping potential is "
  + (h * fnow - p.phi).toFixed(2) + " V";

var lc = 0.002426;
var th = p.theta * Math.PI / 180;
var dl = lc * (1 - Math.cos(th));
var lam = p.lam;
var lp = lam + dl;
var K = 1240 / lam - 1240 / lp;   // eV
var alpha = (1240 / lam) / 511000.0;
var phi = Math.atan(1 / ((1 + alpha) * Math.tan(th / 2 + 1e-9))) * 180 / Math.PI;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.6;
var cx = W * 0.46, cy = H * 0.52;
var L = Math.min(W, H) * 0.42;

// incident photon
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(cx - L * 1.25, cy); ctx.lineTo(cx - 12, cy); ctx.stroke();
ctx.beginPath();
ctx.moveTo(cx - 10, cy); ctx.lineTo(cx - 20, cy - 4); ctx.lineTo(cx - 20, cy + 4);
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
ctx.textAlign = "left";
ctx.fillText("incoming photon, " + lam.toFixed(4) + " nm", 4, cy - 10);

// electron at rest
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 5, 0, Math.PI * 2); ctx.fill();
ctx.textAlign = "center";
ctx.fillText("electron at rest", cx, cy - 12);

// dashed original direction
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + L * 1.1, cy); ctx.stroke();
ctx.setLineDash([]);

// scattered photon
var sx = cx + L * Math.cos(th), sy = cy - L * Math.sin(th);
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(sx, sy); ctx.stroke();
ctx.beginPath();
ctx.moveTo(sx, sy);
ctx.lineTo(sx - 10 * Math.cos(th) - 4 * Math.sin(th), sy + 10 * Math.sin(th) - 4 * Math.cos(th));
ctx.lineTo(sx - 10 * Math.cos(th) + 4 * Math.sin(th), sy + 10 * Math.sin(th) + 4 * Math.cos(th));
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
ctx.textAlign = sx > cx ? "left" : "right";
ctx.fillText("scattered photon, " + lp.toFixed(4) + " nm", sx + (sx > cx ? 6 : -6), sy - 6);

// recoil electron
var rp = phi * Math.PI / 180;
var ex = cx + L * 0.72 * Math.cos(rp), ey = cy + L * 0.72 * Math.sin(rp);
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ex, ey); ctx.stroke();
ctx.beginPath();
ctx.moveTo(ex, ey);
ctx.lineTo(ex - 10 * Math.cos(rp) - 4 * Math.sin(rp), ey - 10 * Math.sin(rp) + 4 * Math.cos(rp));
ctx.lineTo(ex - 10 * Math.cos(rp) + 4 * Math.sin(rp), ey - 10 * Math.sin(rp) - 4 * Math.cos(rp));
ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
ctx.textAlign = "left";
ctx.fillText("recoil electron", ex + 6, ey + 12);

// angle arcs
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.arc(cx, cy, 34, -th, 0); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("theta = " + p.theta.toFixed(0) + " deg", cx + 38, cy - 16);
ctx.beginPath(); ctx.arc(cx, cy, 26, 0, rp); ctx.stroke();
ctx.fillText("phi = " + phi.toFixed(0) + " deg", cx + 30, cy + 26);

out.note = "shift " + dl.toFixed(5) + " nm, scattered wavelength " + lp.toFixed(5)
  + " nm, electron gains " + K.toFixed(1) + " eV";
